{"code":"import json, math, statistics, collections, itertools
ids=[]
for offset in range(0,50,10):
    res = await mcp_call_tool('list_sample_ids', {'run_id': run_id, 'offset': offset, 'limit': 10})
    ids.extend(res['result']['sample_ids'])
# evaluate in batches of 10
results=[]
for i in range(0,50,10):
    batch=ids[i:i+10]
    res = await mcp_call_tool('evaluate_batch', {'run_id': run_id, 'sample_ids': batch})
    results.append(res)
    print('BATCH', i//10, json.dumps(res, indent=2))

# summarize raw returns
records=[]
errors=[]
for res in results:
    r=res.get('result',{}) if isinstance(res,dict) else {}
    if 'evaluations' in r:
        records.extend(r['evaluations'])
    if 'error' in r:
        errors.append(r['error'])
print('num_records', len(records), 'errors', errors)
"}

{"code":"import json, math, statistics, collections
async def main():
    ids=[]
    for offset in range(0,50,10):
        res = await mcp_call_tool('list_sample_ids', {'run_id': run_id, 'offset': offset, 'limit': 10})
        ids.extend(res['result']['sample_ids'])
    results=[]
    for i in range(0,50,10):
        batch=ids[i:i+10]
        res = await mcp_call_tool('evaluate_batch', {'run_id': run_id, 'sample_ids': batch})
        results.append(res)
        print('BATCH', i//10)
        print(json.dumps(res, indent=2))
    records=[]
    errs=[]
    for res in results:
        if isinstance(res, dict):
            if res.get('status')=='ok' and isinstance(res.get('result'), dict):
                rr=res['result']
                if 'evaluations' in rr:
                    records.extend(rr['evaluations'])
            else:
                errs.append(res)
    print('TOTAL_RECORDS', len(records))
    print('ERRS', json.dumps(errs, indent=2))
await main()"}

