{"code":"import json, math, statistics, collections
async def main():
    ids=[]
    offset=0
    while True:
        res = await mcp_call_tool('list_sample_ids', {'run_id': run_id, 'offset': offset, 'limit': BATCH_SIZE})
        print('LIST', offset, res)
        if res['status']!='ok':
            return {'error': res}
        batch = res['result'].get('sample_ids', res['result'])
        if not batch:
            break
        ids.extend(batch)
        if len(batch) < BATCH_SIZE:
            break
        offset += len(batch)
    return {'ids': ids}
result = await main()
print(json.dumps(result))"}

